package build

import (
	"regexp"
	"runtime/debug"
)

const (
	Name        string = "lognav"
	Description string = "Log search for power users"
)

// unknownVersion is reported when neither a module version nor a VCS revision
// is embedded in the build (e.g. built with -buildvcs=false or outside a git
// tree).
const unknownVersion = "unknown"

// shortHashLen is the number of leading hex characters kept from the VCS
// revision, matching the width Go uses in pseudo-versions.
const shortHashLen = 12

// pseudoVersionRE matches the pseudo-version forms generated by the Go tool.
var pseudoVersionRE = regexp.MustCompile(`^v[0-9]+\.(0\.0-|\d+\.\d+-([^+]*\.)?0\.)\d{14}-[A-Za-z0-9]+(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$`)

// version may be stamped by package builds with
// `-X github.com/bevicted/lognav/internal/build.version=<git-ref>`.
var version string

// GetVersion returns the package-stamped version when present. For a local
// build from the git tree it is otherwise the short commit hash, with a
// "+dirty" suffix when the working tree has uncommitted changes. For binaries
// produced by `go install module@version` (which carry no VCS settings) it is
// the module version: a release tag or a Go pseudo-version. It falls back to
// "unknown" when no build information is available.
func GetVersion() string {
	return effectiveVersion(version)
}

func effectiveVersion(stamped string) string {
	if stamped != "" {
		return stamped
	}
	return resolveVersion()
}

// resolveVersion derives the version string from the embedded build info.
func resolveVersion() string {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return unknownVersion
	}
	return versionFromBuildInfo(info)
}

// versionFromBuildInfo prefers the module version for a clean tagged release.
// Other VCS builds use a short commit hash instead of Go's synthesized
// pseudo-version. Builds without VCS settings, such as `go install
// module@version`, use their module version.
func versionFromBuildInfo(info *debug.BuildInfo) string {
	if v := releaseModuleVersion(info.Main.Version); v != "" && !vcsModified(info.Settings) {
		return v
	}

	if v := vcsVersion(info.Settings); v != unknownVersion {
		return v
	}

	if v := info.Main.Version; v != "" && v != "(devel)" {
		return v
	}

	return unknownVersion
}

func releaseModuleVersion(version string) string {
	if version == "" || version == "(devel)" || pseudoVersionRE.MatchString(version) {
		return ""
	}
	return version
}

func vcsModified(settings []debug.BuildSetting) bool {
	for _, setting := range settings {
		if setting.Key == "vcs.modified" {
			return setting.Value == "true"
		}
	}
	return false
}

// vcsVersion builds a "<shorthash>[+dirty]" string from the vcs.* build
// settings, or returns "unknown" when no revision was stamped.
func vcsVersion(settings []debug.BuildSetting) string {
	var revision, modified string
	for _, s := range settings {
		switch s.Key {
		case "vcs.revision":
			revision = s.Value
		case "vcs.modified":
			modified = s.Value
		}
	}

	if revision == "" {
		return unknownVersion
	}

	short := revision
	if len(short) > shortHashLen {
		short = short[:shortHashLen]
	}
	if modified == "true" {
		short += "+dirty"
	}
	return short
}
